// M2 integration candidate: numeric policy, no engine/UI mutation.
const deepFreeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(deepFreeze);Object.freeze(x);}return x;};
export const CONFIG=deepFreeze({id:'equipment-budget-m2-v1',levelGrowth:1.025,level20Budget:40,qualityOffsets:[0,3,7,14,18],ordinaryAffixScales:[1,1.04,1.08,1.12],enhancementPerLevel:.04,enhancementMax:5,successRates:[.9,.8,.6,.4,.2],feeWeights:[1,2,3,5,8],slotCoefficients:{core:.8,weapon:1,helm:.65,armor:1.15,gloves:.65,boots:.65,ring:.8,amulet:.85},statCosts:{atk:1,armor:1,hp:.2}});
export const VARIANTS=deepFreeze({
bow_balanced:{slot:'weapon',atk:.8,armor:0,hp:.2},bow_attack:{slot:'weapon',atk:.9,armor:0,hp:.1},staff_balanced:{slot:'weapon',atk:.75,armor:.05,hp:.2},staff_element:{slot:'weapon',atk:.85,armor:0,hp:.15},
sword_shield_balanced:{slot:'weapon',atk:.65,armor:.25,hp:.1},sword_shield_defensive:{slot:'weapon',atk:.55,armor:.35,hp:.1},greatsword_balanced:{slot:'weapon',atk:.8,armor:.05,hp:.15},greatsword_attack:{slot:'weapon',atk:.9,armor:0,hp:.1},dagger_balanced:{slot:'weapon',atk:.85,armor:0,hp:.15},sword_balanced:{slot:'weapon',atk:.8,armor:.1,hp:.1},
armguard_balanced:{slot:'weapon',atk:.75,armor:.15,hp:.1},armguard_attack:{slot:'weapon',atk:.85,armor:.1,hp:.05},armguard_defensive:{slot:'weapon',atk:.65,armor:.25,hp:.1},
core_primal:{slot:'core',atk:1/3,armor:1/3,hp:1/3},core_molten:{slot:'core',atk:.5,armor:.5,hp:0},core_stone:{slot:'core',atk:0,armor:.5,hp:.5},core_crystal:{slot:'core',atk:.5,armor:0,hp:.5},
axe_balanced:{slot:'weapon',atk:.8,armor:0,hp:.2},axe_attack:{slot:'weapon',atk:.9,armor:0,hp:.1},hammer_balanced:{slot:'weapon',atk:.75,armor:.15,hp:.1},hammer_defensive:{slot:'weapon',atk:.65,armor:.25,hp:.1},
helm_armor:{slot:'helm',atk:.05,armor:.65,hp:.3},helm_vitality:{slot:'helm',atk:.05,armor:.35,hp:.6},armor_armor:{slot:'armor',atk:0,armor:.7,hp:.3},armor_vitality:{slot:'armor',atk:0,armor:.4,hp:.6},gloves_armor:{slot:'gloves',atk:.2,armor:.5,hp:.3},gloves_vitality:{slot:'gloves',atk:.2,armor:.25,hp:.55},boots_armor:{slot:'boots',atk:.05,armor:.6,hp:.35},boots_vitality:{slot:'boots',atk:.05,armor:.3,hp:.65},ring_attack:{slot:'ring',atk:.65,armor:0,hp:.35},ring_element:{slot:'ring',atk:.45,armor:.1,hp:.45},ring_survival:{slot:'ring',atk:.2,armor:.35,hp:.45},amulet_attack:{slot:'amulet',atk:.6,armor:0,hp:.4},amulet_element:{slot:'amulet',atk:.4,armor:.15,hp:.45},amulet_survival:{slot:'amulet',atk:.15,armor:.35,hp:.5}});
export function budgetAt({slot,level,quality=0,enhancement=0}){if(!Object.hasOwn(CONFIG.slotCoefficients,slot)||!Number.isInteger(level)||level<1||level>100||!Number.isInteger(quality)||quality<0||quality>4||!Number.isInteger(enhancement)||enhancement<0||enhancement>5)throw new RangeError('invalid equipment budget');return CONFIG.slotCoefficients[slot]*CONFIG.level20Budget*CONFIG.levelGrowth**(level-20+CONFIG.qualityOffsets[quality])*(1+CONFIG.enhancementPerLevel*enhancement);}
export function deriveEquipmentBase({slot,baseVariant,level,quality=0,enhancement=0}){const v=VARIANTS[baseVariant];if(!v||v.slot!==slot)throw new RangeError('variant/slot mismatch');const budget=budgetAt({slot,level,quality,enhancement:0});const raw=Object.fromEntries(['atk','armor','hp'].map(k=>[k,v[k]===0?0:Math.max(1,Math.round(budget*v[k]/CONFIG.statCosts[k]))]));return enhanceRawBase(raw,enhancement);}
export function enhanceRawBase(raw,level){if(!Number.isInteger(level)||level<0||level>5||!['atk','armor','hp'].every(k=>Number.isSafeInteger(raw[k])&&raw[k]>=0&&raw[k]<=1e12))throw new RangeError('invalid raw base');let prev={...raw};for(let n=1;n<=level;n++){let next=Object.fromEntries(['atk','armor','hp'].map(k=>[k,raw[k]===0?0:Math.max(prev[k],Math.round(raw[k]*(1+.04*n)))]));if(['atk','armor','hp'].every(k=>next[k]===prev[k])){const k=['hp','armor','atk'].find(k=>raw[k]>0);if(k)next[k]++;}prev=next;}return prev;}
export function enhancementFee({level,quality,target}){if(!Number.isSafeInteger(level)||level<1||level>1e12||!Number.isInteger(quality)||quality<0||quality>4||!Number.isInteger(target)||target<1||target>5)throw new RangeError('invalid fee');return Math.ceil((2+level/20)*(1+.2*quality))*CONFIG.feeWeights[target-1];}
export function affixRange(def,quality){if(!Number.isInteger(quality)||quality<0||quality>4||!def||!Number.isSafeInteger(def.min)||!Number.isSafeInteger(def.max)||def.min<0||def.max<def.min||def.max>1e9)throw new RangeError('invalid affix range');const q=Math.min(3,quality),scale=CONFIG.ordinaryAffixScales[q],normal={min:Math.floor(def.min*scale),max:Math.ceil(def.max*scale)};return quality===4?{min:Math.ceil(normal.min*1.1),max:Math.ceil(normal.max*1.1)}:normal;}

export const EXPECTED_VISITS=[80/27,25/3,85/6,25/2,5];
export function expectedEnhancementGold(level,quality){return EXPECTED_VISITS.reduce((s,v,i)=>s+v*enhancementFee({level,quality,target:i+1}),0);}

// New generation / reroll range. Do not apply target quality to inherited rolls.
export const rollRange = affixRange;
export function legalInheritedRange(def){const low=affixRange(def,0),high=affixRange(def,4);return {min:low.min,max:high.max};}
export function validAffixRaw(def,value,sourceQuality=null){try{const r=sourceQuality===null?legalInheritedRange(def):affixRange(def,sourceQuality);return Number.isSafeInteger(value)&&value>=r.min&&value<=r.max;}catch{return false;}}
// Coloring uses recorded roll source, never divine-adjusted display values.
// Legacy rolls without provenance use union range, not recipient quality.
export function affixDisplayRange(def,sourceQuality=null){return sourceQuality===null?legalInheritedRange(def):affixRange(def,sourceQuality);}
